-- Multi-store role assignments, selected-store authorization and audited administration.
set statement_timeout='30s';set lock_timeout='5s';

create table public.salon_permission_catalog(resource text not null,action text not null,label text not null,primary key(resource,action));
insert into public.salon_permission_catalog values
('catalog','read','查看项目商品'),('catalog','write','管理项目商品'),('commission','write','管理提成规则'),('customers','read','查看顾客'),('customers','write','管理顾客'),('finance','write','登记收支'),('inventory','write','管理库存'),('members','read','查看会员'),('members','recharge','会员充值'),('members','write','管理会员'),('orders','checkout','订单收银'),('orders','discount','订单优惠'),('orders','read','查看订单'),('orders','refund','旧退款权限'),('orders','refund_approve','退款审批'),('orders','refund_execute','退款执行'),('orders','refund_read','查看退款'),('orders','refund_request','申请退款'),('orders','write','管理订单'),('payroll','approve','工资审批'),('payroll','generate','工资试算'),('payroll','read','查看工资'),('reports','read','查看报表'),('scheduling','write','管理预约排客'),('staff','write','管理员工'),('settings','role_write','管理角色'),('settings','assignment_write','分配角色与调店'),('audit','read','查看操作日志');

create table public.salon_staff_store_roles(id bigint generated always as identity primary key,organization_id bigint not null,staff_id bigint not null,store_id bigint not null,role_id bigint not null,status text not null default 'active' check(status in('active','ended')),effective_from date not null default current_date,effective_to date,assigned_by_staff_id bigint,reason text not null default '',created_at timestamptz not null default now(),check(effective_to is null or effective_to>=effective_from),unique(organization_id,id),foreign key(organization_id,staff_id) references public.salon_staff(organization_id,id),foreign key(organization_id,store_id) references public.salon_stores(organization_id,id),foreign key(organization_id,role_id) references public.salon_roles(organization_id,id),foreign key(organization_id,assigned_by_staff_id) references public.salon_staff(organization_id,id));
create unique index salon_staff_store_roles_active_idx on public.salon_staff_store_roles(organization_id,staff_id,store_id) where status='active';
create index salon_staff_store_roles_lookup_idx on public.salon_staff_store_roles(organization_id,staff_id,status,store_id);
insert into public.salon_staff_store_roles(organization_id,staff_id,store_id,role_id,effective_from,reason) select organization_id,id,store_id,role_id,effective_from,'基础员工归属回填' from public.salon_staff where role_id is not null;
do $$declare t text;begin foreach t in array array['salon_permission_catalog','salon_staff_store_roles'] loop execute format('alter table public.%I enable row level security',t);execute format('alter table public.%I force row level security',t);execute format('revoke all on table public.%I from public,anon,authenticated',t);execute format('grant all on table public.%I to service_role',t);end loop;end$$;

create or replace function salon_private.assert_staff_permission(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_resource text,p_action text) returns void language plpgsql security invoker set search_path='' as $$begin if not exists(select 1 from public.salon_staff s join public.salon_staff_store_roles a on a.organization_id=s.organization_id and a.staff_id=s.id and a.status='active' and a.effective_from<=current_date and (a.effective_to is null or a.effective_to>=current_date) join public.salon_roles r on r.organization_id=a.organization_id and r.id=a.role_id and r.status='active' join public.salon_role_permissions rp on rp.role_id=r.id where s.id=p_actor_staff_id and s.organization_id=p_organization_id and s.employment_status='active' and (r.data_scope='organization' or a.store_id=p_store_id) and (r.data_scope<>'self' or (p_resource='payroll' and p_action='read')) and rp.resource=p_resource and rp.action=p_action) then raise exception '当前员工没有该门店操作权限';end if;end$$;

create or replace function public.salon_resolve_staff_store(p_actor_staff_id bigint,p_organization_id bigint,p_requested_store_id bigint) returns bigint language plpgsql security invoker set search_path='' as $$begin if not exists(select 1 from public.salon_stores where organization_id=p_organization_id and id=p_requested_store_id and status='active') or not exists(select 1 from public.salon_staff s join public.salon_staff_store_roles a on a.organization_id=s.organization_id and a.staff_id=s.id and a.status='active' and a.effective_from<=current_date and (a.effective_to is null or a.effective_to>=current_date) join public.salon_roles r on r.organization_id=a.organization_id and r.id=a.role_id and r.status='active' where s.organization_id=p_organization_id and s.id=p_actor_staff_id and s.employment_status='active' and (r.data_scope='organization' or a.store_id=p_requested_store_id)) then raise exception '当前员工不能进入该门店';end if;return p_requested_store_id;end$$;

create or replace function public.salon_list_staff_stores(p_actor_staff_id bigint,p_organization_id bigint) returns table(store_id bigint,code text,name text,data_scope text) language plpgsql security invoker set search_path='' as $$begin if not exists(select 1 from public.salon_staff where organization_id=p_organization_id and id=p_actor_staff_id and employment_status='active') then raise exception '员工不存在或已停用';end if;return query with access as(select st.id,st.code,st.name,r.data_scope from public.salon_staff_store_roles a join public.salon_roles r on r.organization_id=a.organization_id and r.id=a.role_id and r.status='active' join public.salon_stores st on st.organization_id=a.organization_id and st.status='active' and (r.data_scope='organization' or st.id=a.store_id) where a.organization_id=p_organization_id and a.staff_id=p_actor_staff_id and a.status='active' and a.effective_from<=current_date and (a.effective_to is null or a.effective_to>=current_date)) select a.id,a.code,a.name,case when bool_or(a.data_scope='organization') then 'organization' else 'store' end from access a group by a.id,a.code,a.name order by a.id;end$$;

create or replace function salon_private.assert_role_scope_admin(p_actor_staff_id bigint,p_organization_id bigint,p_role_id bigint,p_action text) returns void language plpgsql security invoker set search_path='' as $$begin if exists(select 1 from public.salon_roles where organization_id=p_organization_id and id=p_role_id and data_scope='organization') and not exists(select 1 from public.salon_staff_store_roles a join public.salon_roles r on r.organization_id=a.organization_id and r.id=a.role_id and r.data_scope='organization' and r.status='active' join public.salon_role_permissions rp on rp.role_id=r.id and rp.resource='settings' and rp.action=p_action where a.organization_id=p_organization_id and a.staff_id=p_actor_staff_id and a.status='active' and a.effective_from<=current_date and (a.effective_to is null or a.effective_to>=current_date)) then raise exception '只有组织级管理员可以管理组织级角色';end if;end$$;

alter table public.salon_operation_requests drop constraint salon_operation_requests_action_check;
alter table public.salon_operation_requests add constraint salon_operation_requests_action_check check(action in('checkout','refund','inventory_move','customer_create','customer_status','customer_relation','catalog_create','catalog_enable','catalog_status','inventory_count','member_open','member_recharge','member_status','order_create','order_lines','order_status','refund_request','refund_review','refund_execute','finance_entry','staff_create','staff_status','commission_rule','payroll_generate','payroll_review','role_create','role_status','staff_assign','staff_transfer'));

create or replace function public.salon_create_role(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_request_key text,p_name text,p_data_scope text,p_permissions jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$declare v_op public.salon_operation_requests;v_id bigint;v_response jsonb;begin perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'settings','role_write');if nullif(btrim(coalesce(p_name,'')),'') is null or p_data_scope not in('self','store','organization') or jsonb_typeof(p_permissions)<>'array' or jsonb_array_length(p_permissions) not between 1 and 100 or (p_data_scope='self' and exists(select 1 from jsonb_array_elements_text(p_permissions) x where x<>'payroll/read')) or exists(select 1 from jsonb_array_elements_text(p_permissions) x where split_part(x,'/',1)='' or split_part(x,'/',2)='' or split_part(x,'/',3)<>'' or not exists(select 1 from public.salon_permission_catalog c where c.resource=split_part(x,'/',1) and c.action=split_part(x,'/',2))) then raise exception '角色名称、范围或权限无效';end if;if p_data_scope='organization' and not exists(select 1 from public.salon_staff_store_roles a join public.salon_roles r on r.organization_id=a.organization_id and r.id=a.role_id and r.data_scope='organization' and r.status='active' join public.salon_role_permissions rp on rp.role_id=r.id and rp.resource='settings' and rp.action='role_write' where a.organization_id=p_organization_id and a.staff_id=p_actor_staff_id and a.status='active') then raise exception '只有组织级管理员可以创建组织级角色';end if;v_op:=salon_private.claim_request(p_organization_id,p_store_id,p_request_key,'role_create','role_payload',hashtextextended(jsonb_build_object('name',btrim(p_name),'scope',p_data_scope,'permissions',p_permissions)::text,0));if v_op.completed_at is not null then return v_op.response_json;end if;begin insert into public.salon_roles(organization_id,name,data_scope) values(p_organization_id,btrim(p_name),p_data_scope) returning id into v_id;exception when unique_violation then raise exception '角色名称已经存在';end;insert into public.salon_role_permissions(role_id,resource,action) select v_id,split_part(x,'/',1),split_part(x,'/',2) from(select distinct value x from jsonb_array_elements_text(p_permissions))q;insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json) values(p_organization_id,p_store_id,p_actor_staff_id,'role',v_id::text,'create',jsonb_build_object('name',btrim(p_name),'dataScope',p_data_scope,'permissions',p_permissions));v_response:=jsonb_build_object('roleId',v_id,'status','active');update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;end$$;

create or replace function public.salon_set_role_status(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_role_id bigint,p_request_key text,p_status text,p_reason text) returns jsonb language plpgsql security invoker set search_path='' as $$declare v_op public.salon_operation_requests;v_before text;v_response jsonb;begin perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'settings','role_write');if p_status not in('active','disabled') or nullif(btrim(coalesce(p_reason,'')),'') is null then raise exception '角色状态或原因无效';end if;v_op:=salon_private.claim_request(p_organization_id,p_store_id,p_request_key,'role_status','role_status_'||p_status,p_role_id);if v_op.completed_at is not null then return v_op.response_json;end if;select status into v_before from public.salon_roles where organization_id=p_organization_id and id=p_role_id for update;if not found or v_before=p_status then raise exception '角色不存在或已经是目标状态';end if;if p_status='disabled' and exists(select 1 from public.salon_staff_store_roles where organization_id=p_organization_id and role_id=p_role_id and status='active') then raise exception '角色仍有在用员工，不能停用';end if;update public.salon_roles set status=p_status where organization_id=p_organization_id and id=p_role_id;insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,before_json,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'role',p_role_id::text,'status_change',jsonb_build_object('status',v_before),jsonb_build_object('status',p_status),btrim(p_reason));v_response:=jsonb_build_object('roleId',p_role_id,'status',p_status);update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;end$$;

create or replace function public.salon_assign_staff_store_role(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_target_staff_id bigint,p_role_id bigint,p_request_key text,p_reason text) returns jsonb language plpgsql security invoker set search_path='' as $$declare v_op public.salon_operation_requests;v_id bigint;v_response jsonb;begin perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'settings','assignment_write');if nullif(btrim(coalesce(p_reason,'')),'') is null or not exists(select 1 from public.salon_staff where organization_id=p_organization_id and id=p_target_staff_id and employment_status<>'departed') or not exists(select 1 from public.salon_roles where organization_id=p_organization_id and id=p_role_id and status='active') then raise exception '员工、角色或分配原因无效';end if;v_op:=salon_private.claim_request(p_organization_id,p_store_id,p_request_key,'staff_assign','staff_role',hashtextextended(jsonb_build_object('staff',p_target_staff_id,'store',p_store_id,'role',p_role_id)::text,0));if v_op.completed_at is not null then return v_op.response_json;end if;begin insert into public.salon_staff_store_roles(organization_id,staff_id,store_id,role_id,assigned_by_staff_id,reason) values(p_organization_id,p_target_staff_id,p_store_id,p_role_id,p_actor_staff_id,btrim(p_reason)) returning id into v_id;exception when unique_violation then raise exception '员工在该门店已有有效角色';end;insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'staff_store_role',v_id::text,'assign',jsonb_build_object('staffId',p_target_staff_id,'roleId',p_role_id),btrim(p_reason));v_response:=jsonb_build_object('assignmentId',v_id,'status','active');update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;end$$;

create or replace function public.salon_transfer_staff(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_target_staff_id bigint,p_target_store_id bigint,p_target_role_id bigint,p_request_key text,p_effective_date date,p_reason text) returns jsonb language plpgsql security invoker set search_path='' as $$declare v_op public.salon_operation_requests;v_staff public.salon_staff;v_assignment_id bigint;v_response jsonb;begin perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_target_store_id,'settings','assignment_write');if p_target_staff_id=p_actor_staff_id or p_effective_date is null or p_effective_date<>current_date or nullif(btrim(coalesce(p_reason,'')),'') is null or not exists(select 1 from public.salon_stores where organization_id=p_organization_id and id=p_target_store_id and status='active') or not exists(select 1 from public.salon_roles where organization_id=p_organization_id and id=p_target_role_id and status='active') then raise exception '调店参数无效';end if;v_op:=salon_private.claim_request(p_organization_id,p_store_id,p_request_key,'staff_transfer','staff_transfer',hashtextextended(jsonb_build_object('staff',p_target_staff_id,'from',p_store_id,'to',p_target_store_id,'role',p_target_role_id,'date',p_effective_date)::text,0));if v_op.completed_at is not null then return v_op.response_json;end if;select * into v_staff from public.salon_staff where organization_id=p_organization_id and store_id=p_store_id and id=p_target_staff_id and employment_status<>'departed' for update;if not found or p_store_id=p_target_store_id then raise exception '员工不属于原门店或目标门店相同';end if;update public.salon_staff_store_roles set status='ended',effective_to=p_effective_date where organization_id=p_organization_id and staff_id=p_target_staff_id and store_id=p_store_id and status='active';insert into public.salon_staff_store_roles(organization_id,staff_id,store_id,role_id,effective_from,assigned_by_staff_id,reason) values(p_organization_id,p_target_staff_id,p_target_store_id,p_target_role_id,p_effective_date,p_actor_staff_id,btrim(p_reason)) returning id into v_assignment_id;update public.salon_staff set store_id=p_target_store_id,role_id=p_target_role_id,employment_status='active',effective_from=p_effective_date,effective_to=null where organization_id=p_organization_id and id=p_target_staff_id;insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,before_json,after_json,reason) values(p_organization_id,p_target_store_id,p_actor_staff_id,'staff',p_target_staff_id::text,'transfer',jsonb_build_object('storeId',p_store_id,'roleId',v_staff.role_id),jsonb_build_object('storeId',p_target_store_id,'roleId',p_target_role_id,'effectiveDate',p_effective_date),btrim(p_reason));v_response:=jsonb_build_object('staffId',p_target_staff_id,'storeId',p_target_store_id,'assignmentId',v_assignment_id,'status','active');update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;end$$;

create or replace function public.salon_list_audit_events(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_entity_type text default '',p_limit integer default 200) returns setof public.salon_audit_events language plpgsql security invoker set search_path='' as $$begin perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'audit','read');if p_limit not between 1 and 500 then raise exception '日志查询数量无效';end if;return query select * from public.salon_audit_events a where a.organization_id=p_organization_id and a.store_id=p_store_id and (coalesce(p_entity_type,'')='' or a.entity_type=p_entity_type) order by a.occurred_at desc,a.id desc limit p_limit;end$$;

-- Replace the administrative writers with explicit organization-scope escalation guards.
create or replace function public.salon_set_role_status(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_role_id bigint,p_request_key text,p_status text,p_reason text) returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_op public.salon_operation_requests;v_before text;v_response jsonb;
begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'settings','role_write');
 perform salon_private.assert_role_scope_admin(p_actor_staff_id,p_organization_id,p_role_id,'role_write');
 if p_status not in('active','disabled') or nullif(btrim(coalesce(p_reason,'')),'') is null then raise exception '角色状态或原因无效';end if;
 v_op:=salon_private.claim_request(p_organization_id,p_store_id,p_request_key,'role_status','role_status_'||p_status,p_role_id);if v_op.completed_at is not null then return v_op.response_json;end if;
 select status into v_before from public.salon_roles where organization_id=p_organization_id and id=p_role_id for update;if not found or v_before=p_status then raise exception '角色不存在或已经是目标状态';end if;
 if p_status='disabled' and exists(select 1 from public.salon_staff_store_roles where organization_id=p_organization_id and role_id=p_role_id and status='active') then raise exception '角色仍有在用员工，不能停用';end if;
 update public.salon_roles set status=p_status where organization_id=p_organization_id and id=p_role_id;
 insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,before_json,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'role',p_role_id::text,'status_change',jsonb_build_object('status',v_before),jsonb_build_object('status',p_status),btrim(p_reason));
 v_response:=jsonb_build_object('roleId',p_role_id,'status',p_status);update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;
end$$;

create or replace function public.salon_assign_staff_store_role(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_target_staff_id bigint,p_role_id bigint,p_request_key text,p_reason text) returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_op public.salon_operation_requests;v_id bigint;v_response jsonb;
begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'settings','assignment_write');
 perform salon_private.assert_role_scope_admin(p_actor_staff_id,p_organization_id,p_role_id,'assignment_write');
 if nullif(btrim(coalesce(p_reason,'')),'') is null or not exists(select 1 from public.salon_staff where organization_id=p_organization_id and id=p_target_staff_id and employment_status<>'departed') or not exists(select 1 from public.salon_roles where organization_id=p_organization_id and id=p_role_id and status='active') then raise exception '员工、角色或分配原因无效';end if;
 v_op:=salon_private.claim_request(p_organization_id,p_store_id,p_request_key,'staff_assign','staff_role',hashtextextended(jsonb_build_object('staff',p_target_staff_id,'store',p_store_id,'role',p_role_id)::text,0));if v_op.completed_at is not null then return v_op.response_json;end if;
 begin insert into public.salon_staff_store_roles(organization_id,staff_id,store_id,role_id,assigned_by_staff_id,reason) values(p_organization_id,p_target_staff_id,p_store_id,p_role_id,p_actor_staff_id,btrim(p_reason)) returning id into v_id;exception when unique_violation then raise exception '员工在该门店已有有效角色';end;
 insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,after_json,reason) values(p_organization_id,p_store_id,p_actor_staff_id,'staff_store_role',v_id::text,'assign',jsonb_build_object('staffId',p_target_staff_id,'roleId',p_role_id),btrim(p_reason));
 v_response:=jsonb_build_object('assignmentId',v_id,'status','active');update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;
end$$;

create or replace function public.salon_transfer_staff(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_target_staff_id bigint,p_target_store_id bigint,p_target_role_id bigint,p_request_key text,p_effective_date date,p_reason text) returns jsonb language plpgsql security invoker set search_path='' as $$
declare v_op public.salon_operation_requests;v_staff public.salon_staff;v_assignment_id bigint;v_response jsonb;
begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_target_store_id,'settings','assignment_write');
 perform salon_private.assert_role_scope_admin(p_actor_staff_id,p_organization_id,p_target_role_id,'assignment_write');
 if p_target_staff_id=p_actor_staff_id or p_effective_date is null or p_effective_date<>current_date or nullif(btrim(coalesce(p_reason,'')),'') is null or not exists(select 1 from public.salon_stores where organization_id=p_organization_id and id=p_target_store_id and status='active') or not exists(select 1 from public.salon_roles where organization_id=p_organization_id and id=p_target_role_id and status='active') then raise exception '调店参数无效';end if;
 v_op:=salon_private.claim_request(p_organization_id,p_store_id,p_request_key,'staff_transfer','staff_transfer',hashtextextended(jsonb_build_object('staff',p_target_staff_id,'from',p_store_id,'to',p_target_store_id,'role',p_target_role_id,'date',p_effective_date)::text,0));if v_op.completed_at is not null then return v_op.response_json;end if;
 select * into v_staff from public.salon_staff where organization_id=p_organization_id and store_id=p_store_id and id=p_target_staff_id and employment_status<>'departed' for update;if not found or p_store_id=p_target_store_id then raise exception '员工不属于原门店或目标门店相同';end if;
 update public.salon_staff_store_roles set status='ended',effective_to=p_effective_date where organization_id=p_organization_id and staff_id=p_target_staff_id and store_id=p_store_id and status='active';
 insert into public.salon_staff_store_roles(organization_id,staff_id,store_id,role_id,effective_from,assigned_by_staff_id,reason) values(p_organization_id,p_target_staff_id,p_target_store_id,p_target_role_id,p_effective_date,p_actor_staff_id,btrim(p_reason)) returning id into v_assignment_id;
 update public.salon_staff set store_id=p_target_store_id,role_id=p_target_role_id,employment_status='active',effective_from=p_effective_date,effective_to=null where organization_id=p_organization_id and id=p_target_staff_id;
 insert into public.salon_audit_events(organization_id,store_id,actor_staff_id,entity_type,entity_id,action,before_json,after_json,reason) values(p_organization_id,p_target_store_id,p_actor_staff_id,'staff',p_target_staff_id::text,'transfer',jsonb_build_object('storeId',p_store_id,'roleId',v_staff.role_id),jsonb_build_object('storeId',p_target_store_id,'roleId',p_target_role_id,'effectiveDate',p_effective_date),btrim(p_reason));
 v_response:=jsonb_build_object('staffId',p_target_staff_id,'storeId',p_target_store_id,'assignmentId',v_assignment_id,'status','active');update public.salon_operation_requests set response_json=v_response,completed_at=now() where id=v_op.id;return v_response;
end$$;

create or replace function public.salon_list_payroll(p_actor_staff_id bigint,p_organization_id bigint,p_store_id bigint,p_month date default null) returns setof public.salon_payroll_runs language plpgsql security invoker set search_path='' as $$
declare v_non_self boolean;
begin
 perform salon_private.assert_staff_permission(p_actor_staff_id,p_organization_id,p_store_id,'payroll','read');
 select exists(select 1 from public.salon_staff_store_roles a join public.salon_roles r on r.organization_id=a.organization_id and r.id=a.role_id and r.status='active' and r.data_scope in('store','organization') join public.salon_role_permissions rp on rp.role_id=r.id and rp.resource='payroll' and rp.action='read' where a.organization_id=p_organization_id and a.staff_id=p_actor_staff_id and a.status='active' and (r.data_scope='organization' or a.store_id=p_store_id)) into v_non_self;
 return query select * from public.salon_payroll_runs p where p.organization_id=p_organization_id and p.store_id=p_store_id and (p_month is null or p.payroll_month=p_month) and (v_non_self or p.staff_id=p_actor_staff_id) order by p.payroll_month desc,p.id desc;
end$$;

revoke execute on function salon_private.assert_role_scope_admin(bigint,bigint,bigint,text) from public,anon,authenticated;
grant execute on function salon_private.assert_role_scope_admin(bigint,bigint,bigint,text) to service_role;

revoke execute on function public.salon_resolve_staff_store(bigint,bigint,bigint) from public,anon,authenticated;revoke execute on function public.salon_list_staff_stores(bigint,bigint) from public,anon,authenticated;revoke execute on function public.salon_create_role(bigint,bigint,bigint,text,text,text,jsonb) from public,anon,authenticated;revoke execute on function public.salon_set_role_status(bigint,bigint,bigint,bigint,text,text,text) from public,anon,authenticated;revoke execute on function public.salon_assign_staff_store_role(bigint,bigint,bigint,bigint,bigint,text,text) from public,anon,authenticated;revoke execute on function public.salon_transfer_staff(bigint,bigint,bigint,bigint,bigint,bigint,text,date,text) from public,anon,authenticated;revoke execute on function public.salon_list_audit_events(bigint,bigint,bigint,text,integer) from public,anon,authenticated;
grant execute on function public.salon_resolve_staff_store(bigint,bigint,bigint) to service_role;grant execute on function public.salon_list_staff_stores(bigint,bigint) to service_role;grant execute on function public.salon_create_role(bigint,bigint,bigint,text,text,text,jsonb) to service_role;grant execute on function public.salon_set_role_status(bigint,bigint,bigint,bigint,text,text,text) to service_role;grant execute on function public.salon_assign_staff_store_role(bigint,bigint,bigint,bigint,bigint,text,text) to service_role;grant execute on function public.salon_transfer_staff(bigint,bigint,bigint,bigint,bigint,bigint,text,date,text) to service_role;grant execute on function public.salon_list_audit_events(bigint,bigint,bigint,text,integer) to service_role;
